                body: "\\phi(\\vb r,t)\n  =\n  q\n  \\frac{\n    1\n  }{\n    \\abs{\\vb r-\\vb r'}\n  }\n  \\,\n  \\frac{\n    1\n  }{\n    1-\\dfrac{\\vb v\\cdot\\vb n}{c}\n  },",
